@import url('https://fonts.googleapis.com/css2?family=Fraunces:opsz,wght@9..144,400;9..144,500;9..144,600;9..144,700&family=Work+Sans:wght@400;500;600;700&display=swap');

:root {
  --navy: #142433;
  --navy-deep: #0c1720;
  --ivory: #faf7f0;
  --gold: #d9a441;
  --gold-soft: #f1dcaa;
  --clay: #b7562f;
  --leaf: #3f6a52;
  --ink: #1c2a33;
  --ink-soft: #56666e;
  --line: #dcd5c4;
  --radius: 4px;
  --max-width: 1080px;
}

* { box-sizing: border-box; }

html { scroll-behavior: smooth; }

body {
  margin: 0;
  font-family: 'Work Sans', -apple-system, BlinkMacSystemFont, sans-serif;
  color: var(--ink);
  background: var(--ivory);
  line-height: 1.55;
  -webkit-font-smoothing: antialiased;
}

h1, h2, h3, h4 {
  font-family: 'Fraunces', Georgia, serif;
  font-weight: 600;
  color: var(--navy);
  line-height: 1.15;
  margin: 0 0 0.5em;
}

h1 { font-size: clamp(2.1rem, 4vw, 3.4rem); font-weight: 500; }
h2 { font-size: clamp(1.5rem, 2.6vw, 2.1rem); }
h3 { font-size: 1.25rem; }

p { margin: 0 0 1em; color: var(--ink-soft); max-width: 62ch; }

a { color: var(--navy); }

.container {
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 0 28px;
}

/* --------------------------------------------------------- nav --------- */
.site-header {
  border-bottom: 1px solid var(--line);
  background: var(--ivory);
  position: sticky;
  top: 0;
  z-index: 20;
}

.nav {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 18px 28px;
  max-width: var(--max-width);
  margin: 0 auto;
}

.brand {
  font-family: 'Fraunces', serif;
  font-size: 1.3rem;
  font-weight: 600;
  color: var(--navy);
  text-decoration: none;
  display: flex;
  align-items: center;
  gap: 8px;
}

.brand-mark {
  width: 26px;
  height: 26px;
  border-radius: 50%;
  background: var(--gold);
  display: inline-flex;
  align-items: center;
  justify-content: center;
  color: var(--navy-deep);
  font-size: 0.85rem;
  font-weight: 700;
}

.nav-links {
  display: flex;
  align-items: center;
  gap: 26px;
  font-size: 0.95rem;
}

.nav-links a {
  text-decoration: none;
  color: var(--ink);
  font-weight: 500;
}

.nav-links a:hover { color: var(--clay); }

.btn {
  display: inline-block;
  padding: 11px 22px;
  border-radius: var(--radius);
  font-weight: 600;
  font-size: 0.95rem;
  text-decoration: none;
  border: 1px solid transparent;
  cursor: pointer;
  font-family: 'Work Sans', sans-serif;
  transition: transform 0.12s ease, box-shadow 0.12s ease;

}

.btn:active { transform: translateY(1px); }

.btn-primary { background: var(--navy); color: var(--ivory); }
.btn-primary:hover { background: var(--navy-deep); }

.btn-gold { background: var(--gold); color: var(--navy-deep); }
.btn-gold:hover { box-shadow: 0 3px 0 var(--navy); transform: translateY(-2px); }

.btn-outline { background: transparent; border-color: var(--navy); color: var(--navy); }
.btn-outline:hover { background: var(--navy); color: var(--ivory); }

.btn-block { width: 100%; text-align: center; }

/* --------------------------------------------------------- hero -------- */
.hero {
  padding: 76px 0 64px;
  border-bottom: 1px solid var(--line);
}

.hero-grid {
  display: grid;
  grid-template-columns: 1.15fr 0.85fr;
  gap: 56px;
  align-items: center;
}

.hero-copy .kicker {
  color: var(--clay);
  font-weight: 600;
  font-size: 0.95rem;
  margin-bottom: 14px;
  display: block;
}

.hero-actions { display: flex; gap: 14px; margin-top: 28px; flex-wrap: wrap; }

.hero-figure {
  background: var(--navy);
  border-radius: var(--radius);
  padding: 30px;
  color: var(--ivory);
  position: relative;
  overflow: hidden;
}

.hero-figure .pocket-row {
  display: flex;
  flex-direction: column;
  gap: 14px;
}

.pocket-chip {
  display: flex;
  justify-content: space-between;
  align-items: center;
  background: rgba(250,247,240,0.06);
  border: 1px solid rgba(250,247,240,0.14);
  border-radius: var(--radius);

  padding: 14px 16px;
}

.pocket-chip .label { font-size: 0.9rem; color: var(--gold-soft); }
.pocket-chip .amount { font-family: 'Fraunces', serif; font-size: 1.3rem; }

/* ------------------------------------------------------- planner cards - */
.section { padding: 64px 0; }
.section-alt { background: #f3efe3; }

.section-head { max-width: 640px; margin-bottom: 40px; }

.card-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 22px;
}

.plan-card {
  background: #fff;
  border: 1px solid var(--line);
  border-radius: var(--radius);
  padding: 28px;
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.plan-card .icon {
  width: 42px;
  height: 42px;
  border-radius: 50%;
  background: var(--gold-soft);
  color: var(--navy);
  display: flex;
  align-items: center;
  justify-content: center;
  font-family: 'Fraunces', serif;
  font-weight: 600;
}

.plan-card .btn { margin-top: 10px; align-self: flex-start; }

/* ------------------------------------------------------------ forms ---- */
.form-wrap {
  max-width: 560px;
  margin: 0 auto;
  background: #fff;
  border: 1px solid var(--line);
  border-radius: var(--radius);
  padding: 36px;
}

.form-wrap.wide { max-width: 720px; }

label {
  display: block;
  font-weight: 600;
  font-size: 0.9rem;
  color: var(--navy);

  margin-bottom: 6px;
}

.field { margin-bottom: 20px; }

input[type="text"], input[type="number"], input[type="email"],
input[type="password"], select, textarea, input[type="file"] {
  width: 100%;
  padding: 11px 13px;
  border: 1px solid var(--line);
  border-radius: var(--radius);
  font-size: 0.98rem;
  font-family: inherit;
  background: #fdfcf9;
  color: var(--ink);
}

input:focus, select:focus, textarea:focus {
  outline: 2px solid var(--gold);
  outline-offset: 1px;
  border-color: var(--gold);
}

.field-hint { font-size: 0.82rem; color: var(--ink-soft); margin-top: 4px; }

.alert {
  padding: 12px 16px;
  border-radius: var(--radius);
  margin-bottom: 20px;
  font-size: 0.92rem;
}

.alert-error { background: #f8e2da; color: #8a2d10; border: 1px solid #e6b39d; }
.alert-success { background: #e2ecdf; color: #2c4a34; border: 1px solid #b7d2ae; }
.alert-info { background: #eef1f5; color: #2c3e4a; border: 1px solid #c7d3dc; }

.form-footnote { text-align: center; margin-top: 18px; font-size: 0.92rem; }

/* ------------------------------------------------------- results ------- */
.result-summary {
  background: var(--navy);
  color: var(--ivory);
  border-radius: var(--radius);
  padding: 26px 30px;
  margin-bottom: 28px;
}

.result-summary p { color: var(--gold-soft); margin: 0; }

.result-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(260px, 1fr));
  gap: 18px;
}

.result-item {
  background: #fff;
  border: 1px solid var(--line);
  border-radius: var(--radius);
  padding: 20px;

}

.result-item .platform-tag {
  display: inline-block;
  font-size: 0.75rem;
  font-weight: 700;
  letter-spacing: 0.02em;
  color: var(--navy);
  background: var(--gold-soft);
  padding: 3px 9px;
  border-radius: 20px;
  margin-bottom: 10px;
}

.result-item .amount { font-family: 'Fraunces', serif; font-size: 1.3rem; color: var(--navy); }

.tips-box {
  margin-top: 30px;
  padding: 20px 24px;
  border-left: 3px solid var(--gold);
  background: #fff;
}

.tips-box ul { margin: 8px 0 0; padding-left: 20px; color: var(--ink-soft); }

/* -------------------------------------------------------- dashboard ---- */
.dash-grid {
  display: grid;
  grid-template-columns: 1fr 1fr 1fr;
  gap: 18px;
  margin-bottom: 40px;
}

.stat-card {
  background: #fff;
  border: 1px solid var(--line);
  border-radius: var(--radius);
  padding: 22px;
}

.stat-card .num { font-family: 'Fraunces', serif; font-size: 2rem; color: var(--navy); }

table.history-table { width: 100%; border-collapse: collapse; background: #fff; }
table.history-table th, table.history-table td {
  text-align: left;
  padding: 12px 16px;
  border-bottom: 1px solid var(--line);
  font-size: 0.92rem;
}
table.history-table th { color: var(--ink-soft); font-weight: 600; font-size: 0.82rem; text-transform: uppercase; letter-spacing: 0.03em; }

.category-pill {
  display: inline-block;
  padding: 3px 10px;
  border-radius: 20px;
  font-size: 0.78rem;
  font-weight: 600;
  background: var(--gold-soft);
  color: var(--navy);
}

/* ------------------------------------------------------- testimonials -- */
.testi-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 22px;
}

.testi-card {
  background: #fff;
  border: 1px solid var(--line);
  border-radius: var(--radius);
  padding: 26px;
}

.testi-card .quote { font-family: 'Fraunces', serif; font-size: 1.05rem; color: var(--navy); }
.testi-card .name { margin-top: 14px; font-weight: 600; color: var(--ink); font-size: 0.9rem; }
.testi-card .role { color: var(--ink-soft); font-size: 0.85rem; }

/* -------------------------------------------------------------- footer - */
.site-footer {
  border-top: 1px solid var(--line);
  padding: 34px 0;
  margin-top: 60px;
}

.footer-inner {
  display: flex;
  justify-content: space-between;
  align-items: center;
  flex-wrap: wrap;
  gap: 14px;
  font-size: 0.86rem;
  color: var(--ink-soft);
}

.footer-links { display: flex; gap: 18px; }
.footer-links a { color: var(--ink-soft); text-decoration: none; }
.footer-links a:hover { color: var(--navy); }

/* -------------------------------------------------------- utilities ---- */
.text-center { text-align: center; }
.mt-0 { margin-top: 0; }
.mb-lg { margin-bottom: 40px; }
.image-preview { max-width: 220px; border-radius: var(--radius); border: 1px solid var(--line); margin-top: 10px; }

@media (max-width: 860px) {
  .hero-grid, .card-grid, .dash-grid, .testi-grid { grid-template-columns: 1fr; }
  .nav-links { gap: 14px; font-size: 0.85rem; }
}

// Small progressive-enhancement helpers for PocketSmart AI.

document.addEventListener("DOMContentLoaded", () => {
  const outfitInput = document.getElementById("outfit_image");
  if (outfitInput) {
    outfitInput.addEventListener("change", () => {
      const existing = document.getElementById("outfit-preview");
      if (existing) existing.remove();

      const file = outfitInput.files[0];
      if (!file) return;

      const reader = new FileReader();
      reader.onload = (e) => {
        const img = document.createElement("img");
        img.id = "outfit-preview";
        img.className = "image-preview";
        img.src = e.target.result;
        outfitInput.parentElement.appendChild(img);
      };
      reader.readAsDataURL(file);
    });
  }
});

